// Compile all stats
const newLeads = $('Get New Leads (24h)').all();
const hotLeads = $('Get All HOT Leads').all();
const responses = $('Get Responses (24h)').all();
const outreach = $('Get Outreach (24h)').all();
const activeLeads = $('Get All Active Leads').all();

// Count by status
const statusCounts = {};
for (const lead of activeLeads) {
  const status = lead.json.fields?.Status || 'Unknown';
  statusCounts[status] = (statusCounts[status] || 0) + 1;
}

// Count outreach by channel
const emailsSent = outreach.filter(o => o.json.fields?.Channel === 'Email').length;
const smsSent = outreach.filter(o => o.json.fields?.Channel === 'SMS').length;

// Count responses by channel
const emailResponses = responses.filter(r => r.json.fields?.Channel === 'Email').length;
const smsResponses = responses.filter(r => r.json.fields?.Channel === 'SMS').length;

// Calculate response rate (if we have outreach history)
const responseRate = outreach.length > 0 ? 
  ((responses.length / outreach.length) * 100).toFixed(1) : 0;

// Average AI score of new leads
const avgScore = newLeads.length > 0 ? 
  (newLeads.reduce((sum, l) => sum + (l.json.fields?.['AI Score'] || 0), 0) / newLeads.length).toFixed(0) : 0;

// Top sources today
const sourceCounts = {};
for (const lead of newLeads) {
  const source = lead.json.fields?.Source || 'Unknown';
  sourceCounts[source] = (sourceCounts[source] || 0) + 1;
}
const topSources = Object.entries(sourceCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 3)
  .map(([source, count]) => `${source}: ${count}`)
  .join(', ');

// HOT leads needing follow-up (contacted > 24h ago)
const hotNeedingFollowup = hotLeads.filter(l => {
  const lastContact = new Date(l.json.fields?.['Last Contact Date'] || 0);
  const hoursSince = (Date.now() - lastContact) / (1000 * 60 * 60);
  return hoursSince > 24;
}).length;

return [{
  json: {
    stats: {
      newLeads: newLeads.length,
      hotLeads: hotLeads.length,
      hotNeedingFollowup: hotNeedingFollowup,
      totalActive: activeLeads.length,
      emailsSent: emailsSent,
      smsSent: smsSent,
      emailResponses: emailResponses,
      smsResponses: smsResponses,
      totalResponses: responses.length,
      responseRate: responseRate,
      avgNewLeadScore: avgScore,
      topSources: topSources || 'None'
    },
    statusCounts: statusCounts,
    hotLeadsList: hotLeads.slice(0, 5).map(l => ({
      address: l.json.fields?.Address,
      city: l.json.fields?.City,
      owner: l.json.fields?.['Owner Name'],
      score: l.json.fields?.['AI Score']
    }))
  }
}];
